import{_ as e,o as a,c as d,a0 as r}from"./chunks/framework.DzvPB4Y-.js";const p=JSON.parse('{"title":"需求口径与业务规则：同一个数不代表同一种订单","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/frameworks/csp1d/business-scenario.md","filePath":"zh-cn/frameworks/csp1d/business-scenario.md"}'),o={name:"zh-cn/frameworks/csp1d/business-scenario.md"};function i(l,t,n,c,h,s){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="需求口径与业务规则-同一个数不代表同一种订单" tabindex="-1">需求口径与业务规则：同一个数不代表同一种订单 <a class="header-anchor" href="#需求口径与业务规则-同一个数不代表同一种订单" aria-label="Permalink to &quot;需求口径与业务规则：同一个数不代表同一种订单&quot;">​</a></h1><p>完成<a href="./first-slitting.html">第一次卷材分切</a>后，先让应用明确“客户要什么”，再增加设备与兼容规则。需求标签、物理单位、单次方案贡献和方案使用量必须连成一条链。</p><h2 id="_1-先设计一个独立于算法的验收题" tabindex="-1">1. 先设计一个独立于算法的验收题 <a class="header-anchor" href="#_1-先设计一个独立于算法的验收题" aria-label="Permalink to &quot;1. 先设计一个独立于算法的验收题&quot;">​</a></h2><p>假设一个已校验切割方案 P 每执行一次产出两卷 A，每卷 10 kg。下面是业务手算，不是框架会自动从“10”推断单位的输入协议：</p><table tabindex="0"><thead><tr><th>订单</th><th>P 单次贡献</th><th style="text-align:right;">需要的使用次数</th><th>产出</th></tr></thead><tbody><tr><td>A，6 卷</td><td>2 卷</td><td style="text-align:right;">3</td><td>6 卷</td></tr><tr><td>A，60 kg</td><td>20 kg</td><td style="text-align:right;">3</td><td>60 kg</td></tr><tr><td>A，30 kg</td><td>20 kg</td><td style="text-align:right;">不能精确满足</td><td>需明确是否允许超产/其他方案</td></tr></tbody></table><p>最后一行不能悄悄使用 1.5 次不可拆分的方案。若当前配置允许超产，可以使用 2 次并报告 40 kg；若要求精确产量且无其他方案，则不可行。允许范围必须进入模型，不是改一下订单标签。</p><h2 id="_2-先用框架的需求类型表达订单" tabindex="-1">2. 先用框架的需求类型表达订单 <a class="header-anchor" href="#_2-先用框架的需求类型表达订单" aria-label="Permalink to &quot;2. 先用框架的需求类型表达订单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>Kotlin 入口</th><th>Rust 入口</th></tr></thead><tbody><tr><td>传统卷数</td><td><code>ProductDemand.legacyRoll</code></td><td><code>ProductDemand::legacy_roll</code></td></tr><tr><td>传统张数</td><td><code>ProductDemand.legacySheet</code></td><td><code>ProductDemand::legacy_sheet</code></td></tr><tr><td>传统重量</td><td><code>ProductDemand.legacyWeight</code></td><td><code>ProductDemand::legacy_weight</code></td></tr></tbody></table><p>这些 helper 表达需求口径，不会替你补齐产品重量、长度或单位重量信息。采用 quantity 构造时，离散/连续属性还由实际单位决定，不能只看 <code>mode</code>。</p><p>调用第一课的输入与求解入口，按当前需求单位读取 contribution。兼容输入可能保留旧模式标签，不能据此忽略真实数量单位或生产密度。</p><h2 id="_3-明确方案贡献-再调用求解" tabindex="-1">3. 明确方案贡献，再调用求解 <a class="header-anchor" href="#_3-明确方案贡献-再调用求解" aria-label="Permalink to &quot;3. 明确方案贡献，再调用求解&quot;">​</a></h2><ol><li>按稳定产品 ID 建立需求，保留产品的宽度、可选长度和重量来源。</li><li>生成方案时检查 <code>CuttingPlanDemandContribution</code> 的 quantity 与订单单位兼容。卷数订单即使产品有重量，仍应贡献卷数。</li><li>通过各语言的需求贡献构造/计算路径生成贡献，而不是将切片数量直接当 kg；核对幅宽、长度、面密度/单件重量的真实量纲。</li><li>按 <code>Σ contribution × usage</code> 重算每个产品的产出，分别输出超产、欠产与允许界限。</li></ol><p>同一产品的两种计量要求是否需要同时约束，是业务决定；不能让适配器看到相同 ID 就覆盖其中一张订单。</p><h2 id="_4-设备规则放在哪一层" tabindex="-1">4. 设备规则放在哪一层？ <a class="header-anchor" href="#_4-设备规则放在哪一层" aria-label="Permalink to &quot;4. 设备规则放在哪一层？&quot;">​</a></h2><p>“材料 M 不能在设备 X 上加工”可以在单方案可行性检查中判断；“设备 X 本班次最多处理 100 m”需要跨方案汇总约束。后者不能只给每个方案单独检查一次 <code>&lt;=100</code>。</p><p>跨方案规则应接对应上下文/建模管线；若使用列生成，新增规则还需检查 LP、对偶/定价和 final 是否一致参与。末端删除违规方案不保证剩余产出仍满足需求。</p><h2 id="_5-给自己的应用留下三组断言" tabindex="-1">5. 给自己的应用留下三组断言 <a class="header-anchor" href="#_5-给自己的应用留下三组断言" aria-label="Permalink to &quot;5. 给自己的应用留下三组断言&quot;">​</a></h2><ul><li>换需求模式但保持数字不变时，产出单位和贡献公式随之变化；不能仍给出原来的结果。</li><li>禁止一个物料-设备组合后，违规候选不能进入选择；再禁止全部可行组合，应无可交付产出。</li><li>总资源上界收紧后，检查所有方案使用量之和，而不是只检查选中的每条方案。</li></ul><p>与<a href="./../integration.html">公共接入指南</a>一起处理正常无解、技术失败和原生后端报告。可行性恢复或启发式回退也要保留真实状态，不自动升级成最优。</p><p>源码回归命令统一放在<a href="./../verification.html">仓库验证参考</a>；先完成业务输入、调用与结果复核，再按需验证。</p>',20)])])}const _=e(o,[["render",i]]);export{p as __pageData,_ as default};
